create table public.curriculum_sources (id uuid primary key default gen_random_uuid(), organization_id uuid references public.organizations(id) on delete set null, title text not null, authority text not null, document_url text, file_path text, file_hash text, license text, status public.source_status not null default 'imported', version text not null, published_at date, created_by uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (authority,title,version));
create table public.curriculum_items (id uuid primary key default gen_random_uuid(), source_id uuid not null references public.curriculum_sources(id) on delete cascade, level public.school_level not null, step public.ceg_step not null, domain text not null, subdomain text, discipline text not null, competency text not null, learning_objectives text[] not null default '{}', content text not null, period text, page_reference text, created_at timestamptz not null default now());
create index curriculum_items_level_discipline_idx on public.curriculum_items(level,discipline);
